        if (rate == null) {
            rate = rates.saveAndFlush(new Rate(sheetId, grade, value));
        } else {
            rate.setRate(value);
            rates.flush();
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                + " rate=" + value.toPlainString());
        return rate;
    }
}
